@section('content')<div class="content-wrapper"><div class="page-header"><h3 class="page-title">Finance Staff</h3></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>User</th><th>Finance Role</th><th>Fund Accounts</th><th>Status</th><th>Actions</th></tr></thead><tbody>@foreach($users as $user) @php($role=$user->hasRole('Head Finance')?'Head Finance':($user->hasRole('Cashier')?'Cashier':'-')) <tr><td>{{ $user->full_name }}</td><td>{{ $role }}</td><td>{{ $user->authorized_bank_accounts->pluck('account_name')->implode(', ') }}</td><td>{{ $user->status?'Active':'Inactive' }}</td><td>@if($actor->hasRole('School Admin'))<button class="role" data-id="{{ $user->id }}" data-role="Cashier">Assign/Remove Cashier</button><button class="role" data-id="{{ $user->id }}" data-role="Head Finance">Assign/Remove Head Finance</button>@endif @if($actor->hasAnyRole(['School Admin','Head Finance']) && $user->hasRole('Cashier'))<button class="accounts" data-id="{{ $user->id }}">Manage Fund Accounts</button>@endif</td></tr>@endforeach</tbody></table></div></div></div>@endsection
@section('js')<script>const token='{{csrf_token()}}';document.querySelectorAll('.role').forEach(b=>b.onclick=async()=>{let action=prompt('assign or remove');if(!['assign','remove'].includes(action))return;await fetch(`/finance-staff/${b.dataset.id}/role`,{method:'POST',headers:{'X-CSRF-TOKEN':token,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify({role:b.dataset.role,action})});location.reload()});document.querySelectorAll('.accounts').forEach(b=>b.onclick=async()=>{let v=prompt('Comma-separated active account IDs');if(v===null)return;await fetch(`/finance-staff/${b.dataset.id}/accounts`,{method:'PUT',headers:{'X-CSRF-TOKEN':token,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify({account_ids:v?v.split(',').map(Number):[]})});location.reload()});</script>@endsection
